# Every game owns one cancellable timer; old callbacks cannot restart a reset game.
def game_pause(app):
    app.running = False
    app.generation += 1
    if app.timer is not None:
        app.root.after_cancel(app.timer)
        app.timer = None

def game_tick(app, generation):
    if not app.running or generation != app.generation:
        return
    app.timer = None
    game_step(app)
    game_draw(app)
    if app.running and generation == app.generation:
        app.timer = app.root.after(60, lambda: game_tick(app, generation))

def game_start(app):
    if app.running or app.over:
        return
    app.running = True
    app.generation += 1
    app.Board.focus_set()
    game_tick(app, app.generation)

def game_close(app):
    game_pause(app)
    app.root.destroy()

# Seven geometric pieces fall into a ten-by-twenty board.
import random
PIECES = (((0,1),(1,1),(2,1),(3,1)),((1,0),(2,0),(1,1),(2,1)),((1,0),(0,1),(1,1),(2,1)),((1,0),(2,0),(0,1),(1,1)),((0,0),(1,0),(1,1),(2,1)),((0,0),(0,1),(1,1),(2,1)),((2,0),(0,1),(1,1),(2,1)))

def blocks_valid(board, piece, x, y):
    return all(0 <= x+a < 10 and 0 <= y+b < 20 and board[y+b][x+a] == 0 for a,b in piece)

def blocks_clear(board):
    kept = [row[:] for row in board if not all(row)]
    count = 20-len(kept)
    return [[0]*10 for _ in range(count)] + kept, count

def blocks_spawn(app):
    index = random.randrange(len(PIECES))
    app.piece = list(PIECES[index]); app.piece_size = 4 if index == 0 else 2 if index == 1 else 3
    app.bx = 3; app.by = 0
    if not blocks_valid(app.cells,app.piece,app.bx,app.by):
        app.over = True; game_pause(app)

def game_reset(app):
    game_pause(app); app.cells = [[0]*10 for _ in range(20)]; app.lines = 0; app.frames = 0; app.over = False
    blocks_spawn(app); game_draw(app)

def blocks_move(app, dx=0, dy=0, rotate=False):
    if not app.running or app.over:
        return False
    # Rotate within a three-cell square; the long piece uses a four-cell square.
    size = app.piece_size
    candidate = [(size-1-b,a) for a,b in app.piece] if rotate else app.piece
    if blocks_valid(app.cells,candidate,app.bx+dx,app.by+dy):
        app.piece = candidate; app.bx += dx; app.by += dy; game_draw(app); return True
    return False

def blocks_lock(app):
    for a,b in app.piece:
        app.cells[app.by+b][app.bx+a] = 1
    app.cells, count = blocks_clear(app.cells); app.lines += count
    blocks_spawn(app)

def blocks_drop(app):
    if not app.running or app.over:
        return
    while blocks_move(app,dy=1):
        pass
    blocks_lock(app); game_draw(app)

def game_step(app):
    app.frames += 1
    if app.frames % max(2,8-app.lines//3) == 0:
        if not blocks_move(app,dy=1):
            blocks_lock(app)

def game_draw(app):
    c = app.Board; c.delete('all'); size = 25
    for y,row in enumerate(app.cells):
        for x,value in enumerate(row):
            c.create_rectangle(160+x*size,y*size,160+(x+1)*size,(y+1)*size,fill='#5879b4' if value else '#18243a',outline='#293750')
    if not app.over:
        for a,b in app.piece:
            x,y = app.bx+a,app.by+b
            c.create_rectangle(160+x*size,y*size,160+(x+1)*size,(y+1)*size,fill='#ffca55')
    app.Status.configure(text=f'Lines: {app.lines} | '+('Game over' if app.over else 'Arrows move/rotate; Space drops.'))
